import itertools

def is_all_interval(perm):
    diffs = [abs(perm[i] - perm[i+1]) for i in range(8)]
    return sorted(diffs) == list(range(1,9))

for perm in itertools.permutations(range(9)):
    if is_all_interval(perm):
        print(perm)
        break
else:
    print("No solution")
